`timescale 1ns / 1ps

// Select a fixed Multiplier 1.1 configuration generated by TD's IP tool.
// Every branch is port-only; generator-owned options live in its IP XML.
module td_dsp_mult #(
    parameter integer A_WIDTH = 18,
    parameter integer B_WIDTH = 18,
    parameter INPUT_FORMAT = "SIGNED"
) (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire [A_WIDTH-1:0] a,
    input wire [B_WIDTH-1:0] b,
    output wire [A_WIDTH+B_WIDTH-1:0] p
);
    generate
        if (A_WIDTH == 19 && B_WIDTH == 14 && INPUT_FORMAT == "SIGNED") begin : g_dct
            mult_19s14s_p1 u_configured_ip (
                .clk(clk), .ce(en), .rst(!rst_n), .a(a), .b(b), .p(p)
            );
        end else if (A_WIDTH == 25 && B_WIDTH == 16 && INPUT_FORMAT == "UNSIGNED") begin : g_quant
            mult_25u16u_p1 u_configured_ip (
                .clk(clk), .ce(en), .rst(!rst_n), .a(a), .b(b), .p(p)
            );
        end else if (A_WIDTH == 14 && B_WIDTH == 10 && INPUT_FORMAT == "UNSIGNED") begin : g_wb
            mult_14u10u_p1 u_configured_ip (
                .clk(clk), .ce(en), .rst(!rst_n), .a(a), .b(b), .p(p)
            );
        end else if (A_WIDTH == 15 && B_WIDTH == 11 && INPUT_FORMAT == "SIGNED") begin : g_ccm
            mult_15s11s_p1 u_configured_ip (
                .clk(clk), .ce(en), .rst(!rst_n), .a(a), .b(b), .p(p)
            );
        end else if (A_WIDTH == 17 && B_WIDTH == 9 && INPUT_FORMAT == "SIGNED") begin : g_chroma
            mult_17s9s_p1 u_configured_ip (
                .clk(clk), .ce(en), .rst(!rst_n), .a(a), .b(b), .p(p)
            );
        end else if (A_WIDTH == 8 && B_WIDTH == 8 && INPUT_FORMAT == "UNSIGNED") begin : g_luma
            mult_8u8u_p1 u_configured_ip (
                .clk(clk), .ce(en), .rst(!rst_n), .a(a), .b(b), .p(p)
            );
        end else if (A_WIDTH == 18 && B_WIDTH == 18 && INPUT_FORMAT == "SIGNED") begin : g_default
            mult_18s18s_p1 u_configured_ip (
                .clk(clk), .ce(en), .rst(!rst_n), .a(a), .b(b), .p(p)
            );
        end else begin : g_unsupported_configuration
            // An ungenerated shape must fail elaboration rather than infer logic
            // or silently change latency. Generate and qualify a new IP first.
            TD_MULTIPLIER_CONFIGURATION_NOT_GENERATED u_configuration_error ();
        end
    endgenerate
endmodule
